{
  "name": "@workit-dev/core",
  "version": "1.9.3",
  "private": false,
  "description": "Workit shared core — task, policy, evidence, review, decision, worker, and writer state for agentic coding workflows",
  "keywords": [
    "agentic-coding",
    "ai-agents",
    "codex",
    "cursor",
    "mcp",
    "opencode",
    "pi",
    "policy-engine",
    "task-management",
    "typescript",
    "workflow"
  ],
  "homepage": "https://github.com/BrainerVirus/workit#readme",
  "bugs": {
    "url": "https://github.com/BrainerVirus/workit/issues"
  },
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/BrainerVirus/workit.git",
    "directory": "packages/workit-core"
  },
  "files": [
    "src/",
    "schemas/",
    "scripts/",
    "skills/",
    "templates/",
    "README.md",
    "LICENSE"
  ],
  "type": "module",
  "main": "./src/core.ts",
  "exports": {
    "./hooks": "./src/hooks/index.ts",
    "./src/*.ts": "./src/*.ts",
    "./src/*.mjs": "./src/*.mjs",
    "./src/*": "./src/*.ts",
    "./package.json": "./package.json"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@openclaw/fs-safe": "0.8.1",
    "zod": "4.6.5"
  },
  "engines": {
    "node": ">=24"
  }
}
